.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #f0f8ff;
  --vt-surface-deep: #4f83d1;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #ffffff;
  --vt-accent: #4f83d1;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #7cb8eb;
  --vt-accent-on-deep: #e5e50f;
  --vt-line: #e9eaeb;
  position: relative;
  margin: 0;
  background: var(--vt-surface);
  color: var(--vt-ink);
  font-family: 'Noto Sans Display', Arial, sans-serif;
  line-height: 1.6;
  overflow-x: hidden;
}

.root *,
.root *::before,
.root *::after {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1),
.root :where(h2),
.root :where(h3),
.root :where(h4),
.root :where(h5),
.root :where(h6) {
  margin: 0;
  font-weight: 700;
  line-height: 1.2;
}

.root :where(p) {
  margin: 0;
}

.root :where(img) {
  max-width: 100%;
  display: block;
}

.root a:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.topbar {
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
  padding: 10px 0;
}

.topbarIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  align-items: center;
}

.topbarText {
  font-size: 14px;
  color: var(--vt-on-deep);
  display: flex;
  align-items: center;
  gap: 6px;
}

.topbarLabel {
  font-weight: 700;
}

.topbarPhone {
  margin-left: auto;
  font-weight: 700;
  color: var(--vt-on-deep);
}

.topbarPhone:hover {
  color: var(--vt-accent-on-deep);
}

.nav {
  position: absolute;
  top: 48px;
  left: 0;
  right: 0;
  z-index: 10;
  padding: 20px 0;
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: inline-flex;
  align-items: center;
}

.brand {
  font-size: 22px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.navLinks {
  display: flex;
  gap: 24px;
}

.navLink {
  font-weight: 500;
  padding: 8px 0;
  color: var(--vt-on-deep);
}

.navLink:hover {
  color: var(--vt-accent-ink);
}

.hero {
  position: relative;
  overflow: hidden;
  min-height: 680px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 180px 20px 120px;
  color: var(--vt-on-deep);
  background: var(--vt-surface-deep);
}

.heroBg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
}

.heroOverlay {
  position: absolute;
  inset: 0;
  background: var(--vt-surface-deep);
  opacity: 0.65;
}

.heroContent {
  position: relative;
  z-index: 2;
  max-width: 820px;
  margin: 0 auto;
  text-align: center;
}

.heroKicker {
  color: var(--vt-accent-on-deep);
  font-size: 16px;
  letter-spacing: 4px;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.heroTitle {
  color: var(--vt-on-deep);
  font-size: 52px;
  margin-bottom: 16px;
}

.heroHighlight {
  color: var(--vt-accent-on-deep);
}

.heroTagline {
  color: rgba(255, 255, 255, 0.85);
  font-size: 18px;
  max-width: 620px;
  margin: 0 auto 32px;
}

.heroActions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.heroButton {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 15px 30px;
  font-weight: 700;
  font-size: 16px;
  transition: background 0.3s;
}

.heroButton:hover {
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
}

.heroButtonOutline {
  border: 2px solid var(--vt-on-deep);
  color: var(--vt-on-deep);
  border-radius: 100px;
  padding: 13px 28px;
  font-weight: 700;
  font-size: 16px;
  transition: background 0.3s, color 0.3s;
}

.heroButtonOutline:hover {
  background: var(--vt-on-deep);
  color: var(--vt-surface-deep);
}

.heroWave {
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 100%;
  height: 120px;
  z-index: 2;
  pointer-events: none;
}

.intro {
  padding: 100px 20px;
  background: var(--vt-surface);
}

.introIn {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.sectionKicker {
  color: var(--vt-accent);
  font-size: 14px;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 8px;
}

.sectionTitle {
  font-size: 42px;
  margin-bottom: 24px;
}

.introText {
  color: var(--vt-ink-soft);
  margin-bottom: 16px;
}

.introImageWrap {
  position: relative;
}

.introImage {
  border-radius: 20px;
  width: 100%;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08);
}

.introCard {
  position: absolute;
  bottom: -20px;
  right: -20px;
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
  border-radius: 10px;
  padding: 20px 24px;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
}

.introCardLabel {
  display: block;
  font-size: 14px;
  margin-bottom: 4px;
}

.introCardPhone {
  font-size: 18px;
  font-weight: 700;
  color: var(--vt-on-deep);
}

.services {
  background: var(--vt-surface-2);
  padding: 100px 20px;
}

.servicesIn {
  max-width: 1200px;
  margin: 0 auto;
}

.servicesGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.serviceCard {
  background: var(--vt-surface);
  border-radius: 10px;
  overflow: hidden;
  display: grid;
  grid-template-columns: 200px 1fr;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.06);
}

.serviceCardFull {
  grid-template-columns: 1fr;
}

.serviceImageWrap {
  position: relative;
  overflow: hidden;
  min-height: 180px;
}

.serviceImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s;
}

.serviceCard:hover .serviceImage {
  transform: scale(1.03);
}

.serviceBody {
  padding: 24px;
  position: relative;
}

.serviceNum {
  position: absolute;
  top: 16px;
  right: 16px;
  font-size: 12px;
  font-weight: 700;
  color: var(--vt-accent);
  background: var(--vt-surface-2);
  border-radius: 20px;
  padding: 4px 10px;
}

.serviceTitle {
  font-size: 22px;
  margin-bottom: 8px;
}

.serviceDesc {
  color: var(--vt-ink-soft);
  font-size: 15px;
  margin-bottom: 16px;
}

.serviceChip {
  display: inline-block;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 20px;
  padding: 6px 12px;
  font-size: 13px;
  margin-right: 8px;
}

.portfolio {
  padding: 100px 20px;
  background: var(--vt-surface);
}

.portfolioIn {
  max-width: 1200px;
  margin: 0 auto;
}

.portfolioGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.portfolioItem {
  position: relative;
  border-radius: 10px;
  overflow: hidden;
  margin: 0;
}

.portfolioImage {
  width: 100%;
  aspect-ratio: 1;
  object-fit: cover;
  transition: transform 0.5s;
}

.portfolioItem:hover .portfolioImage {
  transform: scale(1.05);
}

.portfolioCaption {
  position: absolute;
  inset: auto 0 0 0;
  padding: 20px;
  background: linear-gradient(transparent, rgba(0, 0, 0, 0.7));
  color: var(--vt-on-deep);
}

.portfolioCaption h3 {
  color: var(--vt-on-deep);
  font-size: 18px;
  margin-bottom: 4px;
}

.portfolioCaption p {
  color: rgba(255, 255, 255, 0.8);
  font-size: 13px;
}

.contact {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 100px 20px;
}

.contactIn {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.contact .sectionKicker,
.contact .sectionTitle {
  color: var(--vt-on-deep);
}

.contactText {
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 24px;
}

.contactPhone {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 14px 28px;
  display: inline-block;
  font-weight: 700;
}

.contactPhone:hover {
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
}

.social {
  margin-top: 24px;
}

.footer {
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
  padding: 60px 20px 0;
}

.footerIn {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 40px;
  align-items: center;
  justify-content: space-between;
}

.footerBrand {
  min-width: 200px;
}

.footerTag {
  color: rgba(255, 255, 255, 0.85);
  max-width: 320px;
}

.footerNav {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.footerNav a {
  color: var(--vt-on-deep);
  font-weight: 500;
}

.footerNav a:hover {
  color: var(--vt-accent-on-deep);
}

.footerBottom {
  max-width: 1200px;
  margin: 40px auto 0;
  border-top: 1px solid var(--vt-line);
  padding: 20px 0;
  display: flex;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 14px;
}

.floatingCall {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 100;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 100px;
  padding: 14px 22px;
  font-weight: 700;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  transition: background 0.3s;
}

.floatingCall:hover {
  background: var(--vt-accent-ink);
  color: var(--vt-on-deep);
}

@media (prefers-reduced-motion: reduce) {
  .root * {
    transition: none;
    animation: none;
  }
}

@media (max-width: 991px) {
  .heroTitle {
    font-size: 42px;
  }

  .sectionTitle {
    font-size: 36px;
  }

  .introIn,
  .contactIn {
    grid-template-columns: 1fr;
  }

  .servicesGrid {
    grid-template-columns: 1fr;
  }

  .portfolioGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .nav {
    position: static;
